    record.update(classification='SOURCE_FIELDS_CONTRADICT',rdkit_and_reference_library_agree=off[1]==d['inchi'] and off[3]==d['inchikey'],priorities='OH oxygen > ethyl carbon ([C,H,H]) > methyl carbon ([H,H,H]) > implicit H; wedge narrow end is atom 2 (1-based), bond 2->3. Explicit molecular-file geometry and wedge give R for RW12, S for RW17.',independent_documentary_support='JST Nikkaji R J9.277K and S J9.275D publish matching name/SMILES/InChI triplets; independent curation ancestry relative to PubChem/NIST is NOT established.',conclusion='The exported molecular file and named configuration agree under both installed interpreters. Published NIST InChI/key encode the opposite configuration. Wedge narrow-end and default absolute-stereo conventions do not explain away this contradiction. Root cause/version history inside NIST is unknown; no curator correction or expert sign-off is claimed.')
